$dump = 'C:\Windows\Minidump\091826-20921-01.dmp'
if (-not (Test-Path $dump)) { "DUMP MISSING: $dump"; return }
$fi = Get-Item $dump
"dump: $($fi.Name)  $($fi.Length) bytes  written $($fi.LastWriteTime)"
$b = [System.IO.File]::ReadAllBytes($dump)
"signature: " + [System.Text.Encoding]::ASCII.GetString($b,0,4)
$nStreams = [BitConverter]::ToUInt32($b,8)
$dirRva   = [BitConverter]::ToUInt32($b,12)
"streams: $nStreams"
$modRva = 0
for ($i=0; $i -lt $nStreams; $i++) {
  $o = $dirRva + $i*12
  if ([BitConverter]::ToUInt32($b,$o) -eq 4) { $modRva = [BitConverter]::ToUInt32($b,$o+8) }
}
if ($modRva -eq 0) { "NO ModuleListStream in this dump"; return }
$count = [BitConverter]::ToUInt32($b,$modRva)
"modules: $count"
$mods = @()
for ($i=0; $i -lt $count; $i++) {
  $o    = $modRva + 4 + $i*108
  $base = [BitConverter]::ToUInt64($b,$o)
  $size = [BitConverter]::ToUInt32($b,$o+8)
  $nRva = [BitConverter]::ToUInt32($b,$o+20)
  $nLen = [BitConverter]::ToUInt32($b,$nRva)
  $name = [System.Text.Encoding]::Unicode.GetString($b,$nRva+4,$nLen)
  $mods += [pscustomobject]@{ Base=$base; End=$base+$size; Size=$size; Name=(Split-Path $name -Leaf) }
}
$fault = [UInt64]'0xfffff8038d062129'
"faulting instruction: 0x{0:x}" -f $fault
$hit = $mods | Where-Object { $fault -ge $_.Base -and $fault -lt $_.End }
if ($hit) {
  "FAULTING MODULE: $($hit.Name)   base 0x{0:x}  size {1}  offset +0x{2:x}" -f $hit.Base, $hit.Size, ($fault - $hit.Base)
} else {
  "no module contains the faulting address; nearest below:"
  $mods | Where-Object { $_.Base -lt $fault } | Sort-Object Base -Descending | Select-Object -First 8 |
    ForEach-Object { "  {0,-28} base 0x{1:x}  end 0x{2:x}" -f $_.Name, $_.Base, $_.End }
}
"--- third-party / graphics modules present in the dump ---"
